package com.hms.notifications;
import java.util.*; import org.springframework.core.env.Environment; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/notifications/provider-health") public class NotificationProviderHealthController {private final Environment environment;public NotificationProviderHealthController(Environment e){environment=e;} @GetMapping public Map<String,Object> health(@PathVariable String tenantSlug){String provider=environment.getProperty("hms.notifications.provider","mock");Map<String,Object> result=new LinkedHashMap<>();result.put("provider",provider);result.put("dispatchEnabled",Boolean.parseBoolean(environment.getProperty("hms.notifications.dispatch-enabled","false")));result.put("channels",List.of(channel("SMS"),channel("EMAIL"),channel("WHATSAPP")));return result;} private Map<String,Object> channel(String name){String endpoint=environment.getProperty("hms.notifications.webhook."+name.toLowerCase());return Map.of("channel",name,"configured",endpoint!=null&&!endpoint.isBlank());}}
